const base = (number) => {
  const spec = baseWeekSpecs.find((item) => item.number === number);
  if (!spec) throw new Error(`Semana-base ${number} não encontrada.`);
  return spec;
};

const periods = [
  "03–09 ago", "10–16 ago", "17–23 ago", "24–30 ago", "31 ago–06 set", "07–13 set",
  "14–20 set", "21–27 set", "28 set–04 out", "05–11 out", "12–18 out", "19–25 out",
  "26 out–01 nov", "02–08 nov", "09–15 nov", "16–22 nov", "23–29 nov", "30 nov–06 dez",
  "07–13 dez", "14–20 dez", "21–27 dez", "28 dez–03 jan", "04–10 jan", "11–17 jan",
];

function mergeResources(...sets) {
  return {
    books: [...new Set(sets.flatMap((item) => item.books))],
    videos: [...new Set(sets.flatMap((item) => item.videos))],
    articles: [...new Set(sets.flatMap((item) => item.articles))],
  };
}

function buildWeek(number, baseNumbers, overrides) {
  const sources = baseNumbers.map(base);
  return {
    ...sources[0],
    ...overrides,
    number,
    period: periods[number - 1],
    block: overrides.blocks[0],
    blocks: overrides.blocks,
    resources: overrides.resources ?? mergeResources(...sources.map((item) => item.resources)),
    sourceOrder: overrides.sourceOrder,
    evaluationFocus: overrides.evaluationFocus ?? [],
  };
}

function modelWeek({ number, baseNumbers, title, blocks, sourceOrder, content, focus, formula, mathExplanation, evaluationFocus, project, resources }) {
  const primary = blocks[0].toLocaleLowerCase("pt-BR");
  return buildWeek(number, baseNumbers, {
    title, blocks, sourceOrder, content, resources,
    summary: `${focus} Conecte conceito, implementação, avaliação e decisão bancária sem perder de vista quando o método é ou não é adequado.`,
    foundation: `${focus} O domínio exige explicar representação, função objetivo ou hipótese, parâmetros aprendidos e comportamento fora da amostra. O algoritmo não deve ser avaliado isoladamente da população, janela temporal e custo da decisão.`,
    mechanism: `Comece por um baseline, prepare os dados sem leakage, ajuste somente no treino e compare alternativas no mesmo protocolo. Depois examine erros, estabilidade temporal, segmentos, calibração quando houver probabilidade e custo operacional antes de escolher o modelo.`,
    formula,
    mathExplanation,
    bankApplication: `Aplique ${title.toLocaleLowerCase("pt-BR")} a crédito, fraude, cobrança ou propensão somente quando suas hipóteses e seu custo forem compatíveis com a decisão. O banco precisa de evidência fora do tempo, impacto por segmento, explicação, monitoramento e fallback.`,
    cases: [`Escolha de ${primary} para uma decisão de crédito com corte temporal.`, `Comparação de alternativas sob custo de falso positivo, falso negativo ou erro financeiro.`, `Monitoramento de estabilidade, qualidade e desempenho por segmento.`],
    pitfalls: ["Vazamento entre treino, validação e teste", "Escolha por uma única métrica sem baseline ou custo", "Tuning excessivo e ausência de validação out-of-time"],
    outcomes: [`Explicar ${title} sem depender da biblioteca`, "Implementar pipeline reproduzível", "Escolher métricas coerentes com o problema", "Defender aplicação, limites e monitoramento bancário"],
    evaluationFocus,
    project,
  });
}

